const displayModuleLabel = (label: string) => label === "Pessoas" ? "Equipa" : label;
const notificationModuleFor = (notification: FinanceRecord) => {
  const source = String(notification.source_type || notification.type || "").toLowerCase();
  const target = String(notification.target_url || "").toLowerCase();
  if (target.startsWith("/inbox-interna") || source === "internal_message") return "Inbox interna";
  if (target.startsWith("/utilizadores") || source.includes("user")) return "Utilizadores";
  if (target.startsWith("/pessoas") || source.includes("employee")) return "Pessoas";
  if (target.startsWith("/recursos-humanos") || source.startsWith("hr_")) return "Recursos Humanos";
  if (target.startsWith("/financas") || source.includes("finance") || source.includes("withdrawal") || source.includes("payment")) return "Finanças";
  if (target.startsWith("/microcredito") || source.includes("loan") || source.includes("microcredit")) return "Triunfal Microcrédito";
  if (target.startsWith("/apoio-cliente") || source.includes("support") || source.includes("ticket") || source.includes("complaint")) return "Apoio ao Cliente";
  if (target.startsWith("/caixa-de-entrada") || source.includes("inbox_message")) return "Caixa de Entrada";
  if (target.startsWith("/marketing/vagas") || source.includes("vacancy") || source.includes("job")) return "Vagas";
  if (target.startsWith("/marketing/conteudos") || source.includes("news") || source.includes("content")) return "Site Institucional";
  if (target.startsWith("/marketing") || source.includes("marketing") || source.includes("campaign")) return "Marketing";
  if (target.startsWith("/field") || source.includes("kyc") || source.includes("field")) return "Operações de Campo";
  if (target.startsWith("/relatorios") || source.includes("report")) return "Relatórios";
  if (target.startsWith("/projectos-tarefas") || target.startsWith("/minhas-tarefas") || source.includes("task") || source.includes("project")) return "Projectos e Tarefas";
  if (target.startsWith("/notificacoes") || source.includes("notification") || source.includes("manual_communication")) return "Centro de Notificações";
  if (target.startsWith("/")) return null;
  return "Centro de Notificações";
};
const notificationHref = (notification: FinanceRecord) => {
  const direct = String(notification.target_url || "").trim();
  const metadata = notification.metadata && typeof notification.metadata === "object" ? notification.metadata as Record<string, unknown> : {};
  const coreCaseId = String(metadata.support_case_id || metadata.case_id || "").trim();
  if (direct.startsWith("/apoio-cliente") && !/[?&]ticket=/.test(direct) && coreCaseId) {
    return `${direct}${direct.includes("?") ? "&" : "?"}ticket=core:${encodeURIComponent(coreCaseId)}`;
  }
  if(direct.startsWith("/microcredito")&&!/[?&]application=/.test(direct)&&/^[0-9a-f-]{36}$/i.test(String(notification.source_id||"")))return `${direct}${direct.includes("?")?"&":"?"}application=${encodeURIComponent(String(notification.source_id))}`;
  if (direct.startsWith("/") && direct !== "/" && !direct.startsWith("//")) return direct;
  const source = `${String(notification.source_type || notification.type || "")} ${String(notification.title || "")} ${String(notification.body || "")}`.toLowerCase();
  if (["order", "delivery", "ride", "trip", "journey", "travel"].some(value => source.includes(value))) return "/mapa-operacional";
  if (source.includes("dispute") || source.includes("complaint") || source.includes("support") || source.includes("ticket") || source.includes("whatsapp") || source.includes("message")) return "/apoio-cliente";
  if (source.includes("kyc") || source.includes("field") || source.includes("courier") || source.includes("restaurant")) return "/field";
  if (["service_request", "service request", "booking", "appointment", "professional_request"].some(value => source.includes(value))) return "/plataformas?platform=mestre24&tab=pedidos";
  if (source.includes("task") || source.includes("project")) return "/projectos-tarefas";
  if (source.includes("finance") || source.includes("withdraw") || source.includes("payment")) return "/financas";
  if (source.includes("loan") || source.includes("credit")) return /^[0-9a-f-]{36}$/i.test(String(notification.source_id||""))?`/microcredito?application=${encodeURIComponent(String(notification.source_id))}`:"/microcredito";
  if (source.includes("user") || source.includes("profile")) return "/utilizadores";
  return routeByModule[notificationModuleFor(notification) || "Centro de Notificações"] || "/notificacoes";
};
const notificationActionLabel = (notification: FinanceRecord) => {
  const source = `${String(notification.source_type || notification.type || "")} ${String(notification.title || "")} ${String(notification.body || "")}`.toLowerCase();
  if (source.includes("kyc") || source.includes("field")) return "Rever KYC";
  if (source.includes("support") || source.includes("ticket") || source.includes("message") || source.includes("whatsapp") || source.includes("dispute")) return "Abrir mensagem";
  if (["order", "delivery", "ride", "trip", "journey", "travel"].some(value => source.includes(value))) return "Acompanhar rota";
  if (["service_request", "service request", "booking", "appointment", "professional_request"].some(value => source.includes(value))) return "Abrir pedido";
  return "Abrir origem";
};
const notificationSummary = (notification: FinanceRecord) => {
  const source = String(notification.source_type || notification.type || "").toLowerCase();
  const title = String(notification.title || "Notificação").trim();
  const body = String(notification.body || "").trim();
  const reference = String(notification.source_id || "").trim();
  const platform = notificationPlatformFor(notification);
  if (source.includes("field_kyc") || source.includes("kyc")) return `Novo KYC para revisão · ${platform}${reference ? ` · #${reference.slice(0, 12)}` : ""}`;
  if (source.includes("support") || source.includes("ticket") || source.includes("message") || source.includes("whatsapp")) return `${title} · ${platform}${body ? ` · ${body}` : ""}`;
  if (source.includes("platform_event") || source.includes("order") || source.includes("delivery") || source.includes("ride") || source.includes("trip")) return `${title} · ${platform}${reference ? ` · #${reference.slice(0, 12)}` : body ? ` · ${body}` : ""}`;
  if (body) return body;
  return `${title}${reference ? ` · #${reference.slice(0, 12)}` : ""}`;
};
const notificationPlatformFor = (notification: FinanceRecord) => {
  const explicit = String(notification.platform_name || notification.platform || notification.platform_slug || "").trim().toLowerCase();
  const source = String(notification.source_type || notification.type || "").toLowerCase();
  const text = `${explicit} ${source} ${String(notification.title || "")} ${String(notification.body || "")}`;
  if (text.includes("mestre24") || text.includes("mestre 24")) return "Mestre24";
  if (text.includes("sarca")) return "SARCA";
  if (text.includes("comunhao") || text.includes("comunhão") || text.includes("igreja")) return "Comunhão";
  if (text.includes("market") || text.includes("taomoz")) return "DeliGo Market";
  if (text.includes("deligo") || text.includes("eats")) return "DeliGo";
  return "Central";
};
const notificationShouldPop = (notification: FinanceRecord) => {
  const source = `${String(notification.source_type || notification.type || "")} ${String(notification.title || "")} ${String(notification.body || "")}`.toLowerCase();
  const operational = ["order", "delivery", "ride", "trip", "journey", "travel", "service_request", "service request", "booking", "kyc", "ticket", "support", "dispute"].some(value => source.includes(value));
  const priority = String(notification.priority || "normal").toLowerCase();
  return operational && !source.includes("manual_communication") && (priority !== "low" || source.includes("ride") || source.includes("trip") || source.includes("service_request"));
};

